import { useFrame } from '@react-three/fiber'
import { useEffect, useMemo, useRef } from 'react'
import * as THREE from 'three'
import type { LaserHandle, LaserOwner, WorldState } from './types'

const MAX_PROJECTILE_LIGHTS = 12

interface LaserProps {
  id: string
  owner: LaserOwner
  origin: THREE.Vector3
  direction: THREE.Vector3
  speed: number
  world: WorldState
  /** Every active projectile keeps its light; this gates expensive light work. */
  lightEnabled: boolean
  onExpired: (id: string) => void
  register: (handle: LaserHandle) => void
  unregister: (id: string) => void
}

export function Laser({ id, owner, origin, direction, speed, world, lightEnabled, onExpired, register, unregister }: LaserProps) {
  const mesh = useRef<THREE.Mesh>(null)
  const group = useRef<THREE.Group>(null)
  const handle = useRef<LaserHandle>({
    id,
    owner,
    position: origin.clone(),
    previousPosition: origin.clone(),
    alive: true,
  })
  const expired = useRef(false)
  const normalizedDirection = useMemo(() => direction.clone().normalize(), [direction])
  const orientation = useMemo(
    () => new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 0, 1), normalizedDirection),
    [normalizedDirection],
  )
  const velocity = useMemo(() => normalizedDirection.clone().multiplyScalar(speed), [normalizedDirection, speed])

  useEffect(() => {
    register(handle.current)
    return () => unregister(id)
  }, [id, register, unregister])

  useFrame((_, delta) => {
    if (!group.current || !handle.current.alive) {
      if (!expired.current) {
        expired.current = true
        onExpired(id)
      }
      return
    }
    handle.current.previousPosition.copy(handle.current.position)
    // Simulation publishes the same clamped step to all moving entities.
    const stepDelta = world.stepDelta || Math.min(delta, 0.1)
    group.current.position.addScaledVector(velocity, stepDelta)
    // Collision reads the projectile's world position, not the child mesh's local coordinates.
    group.current.getWorldPosition(handle.current.position)
    if (handle.current.position.z < -120 || handle.current.position.z > 14) {
      handle.current.alive = false
      if (!expired.current) {
        expired.current = true
        onExpired(id)
      }
    }
  })

  const color = owner === 'player' ? '#76f5ff' : '#ff685c'
  return (
    <group ref={group} position={origin}>
      <mesh ref={mesh} quaternion={orientation}>
        <boxGeometry args={[0.08, 0.08, owner === 'player' ? 1.4 : 1.05]} />
        <meshBasicMaterial color={color} toneMapped={false} />
      </mesh>
      <pointLight
        color={color}
        intensity={owner === 'player' ? 3.4 : 2.2}
        distance={5.5}
        visible={lightEnabled}
        // Keep a pointLight on every projectile while limiting active lights.
        userData={{ projectileLightCap: MAX_PROJECTILE_LIGHTS }}
      />
    </group>
  )
}

