import { useFrame } from '@react-three/fiber'
import { useMemo, useRef } from 'react'
import * as THREE from 'three'
import type { WorldState } from './types'

const VERTEX_SHADER = /* glsl */ `
  uniform float uTime;
  uniform float uScroll;
  uniform float uTileZ;
  varying float vHeight;
  varying vec2 vTerrainPos;

  float heightAt(vec2 p) {
    float canyon = sin(p.x * 0.075 + uScroll * 0.012) * 1.6;
    float ridge = sin(p.x * 0.21 + p.y * 0.035) * 0.42;
    float chop = sin(p.x * 0.8 + p.y * 0.15) * 0.12;
    return -1.6 + canyon + ridge + chop;
  }

  void main() {
    // The plane is rotated -90° around X: local +Y maps to world -Z.
    // Subtracting keeps the shader's world-Z field aligned with the wrapped mesh.
    vec2 terrainPos = vec2(position.x, uTileZ - position.y);
    vTerrainPos = terrainPos;
    vec3 displaced = position;
    displaced.z = heightAt(terrainPos);
    vHeight = displaced.z;
    gl_Position = projectionMatrix * modelViewMatrix * vec4(displaced, 1.0);
  }
`

const FRAGMENT_SHADER = /* glsl */ `
  varying float vHeight;
