function Simulation({ flight, running, bombs, gameOver, onBomb, onPlayerFire, onEncounter, onBarrel, onDistance }: SimulationProps) {
  const encounterCursor = useRef(0)
  const lastShot = useRef(0)
  const lastHudUpdate = useRef(0)

  useFrame((_, delta) => {
    if (!running || gameOver.current) return
    const { world, player, input } = flight
    const boundedDelta = world.resumePending ? Math.min(delta, 0.05) : Math.min(delta, 0.1)
    // Publish one step for every frame participant, including lasers and
    // enemies. This prevents a resumed tab from moving projectiles farther
    // than the collision simulation believes it moved.
    world.stepDelta = boundedDelta
    world.resumePending = false
    world.time += boundedDelta
    const now = world.time
    world.boost = input.keys.has('ShiftLeft') || input.keys.has('ShiftRight')
    world.distance += boundedDelta * world.speed * (world.boost ? 1.75 : 1)

    while (encounterCursor.current < ENCOUNTERS.length && world.distance >= ENCOUNTERS[encounterCursor.current].at) {
      const index = encounterCursor.current
      onEncounter(ENCOUNTERS[index], index)
      encounterCursor.current += 1
    }

    if (input.justPressed.has('KeyE')) onBarrel(1)
    if (input.justPressed.has('KeyQ') && bombs > 0) onBomb()
    if (input.keys.has('Space') && now - lastShot.current > 0.16) {
      lastShot.current = now
      const origin = player.position.clone()
      origin.z -= 1.2
      onPlayerFire(origin)
    }


    if (now - lastHudUpdate.current > 0.1) {
      lastHudUpdate.current = now
      onDistance(world.distance)
    }
    input.justPressed.clear()
  }, -2)
  return null
}

