function CollisionSystem({ running, flight, lasers, enemies, gameOver, onHitEnemy, onDamagePlayer, onEnemyBodyCollision, onStatus, onScore }: CollisionSystemProps) {
  useFrame(() => {
    if (!running || gameOver.current) return
    const { player, world } = flight
    for (const laser of lasers.values()) {
